import subprocess
import os
import json
from datetime import datetime
def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    if not os.path.exists(script_name):
        raise FileNotFoundError(f"The script file {script_name} does not exist.")

    start_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    try:
        result = subprocess.run(['sh', script_name], capture_output=True)
        exit_status = result.returncode
    except Exception as e:
        raise RuntimeError(f"An error occurred while executing the script: {e}")

    end_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    log_data = {
        'start_time': start_time,
        'end_time': end_time,
        'exit_status': exit_status
    }

    try:
        log_dir = os.path.dirname(log_file)
        if log_dir and not os.path.exists(log_dir):
            os.makedirs(log_dir)
        with open(log_file, 'w') as f:
            json.dump(log_data, f)
    except Exception as e:
        pass

    return log_data

import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == "Windows":
        process = subprocess.Popen(['cmd', '/c', 'start', url])
    elif system == "Darwin":
        process = subprocess.Popen(['open', url])
    else:
        process = subprocess.Popen(['xdg-open', url])

    return code if (code := process.wait()) is not None else 0

import subprocess
import os
import random
def task_func(directory, file_list):
    if not file_list:
        return None

    selected_file = random.choice(file_list)
    file_path = os.path.join(directory, selected_file)

    process = subprocess.Popen([file_path])
    return process.poll()
